mapper.select:
select t1.* from TBL_CEA_PEOPLE_LEAVE t1
left join TBL_STAFF t2 on t2.STAFFID = t1.STAFFID
where 1=1
and (t1.creator = #{param.creator}

   or t1.creator in (SELECT DISTINCT STAFFID FROM TBL_USER_ORGRELATION WHERE DEPTID IN (${param.getDeptIds}))
)

    and t1.STAFFID = #{param.staffId}


    and t2.REALNAME like concat('%',concat(#{param.staffName},'%'))


    and t1.STAFFNUMBER like concat('%',concat(#{param.staffNumber},'%'))


    and t1.CREATEDTIME >= #{param.startTime} and t1.CREATEDTIME < #{param.endTime}

order by t1.id desc
